def solve_linear(A, b):
    n = len(b)
    M = [A[i][:] + [b[i]] for i in range(n)]
    for col in range(n):
        pivot = max(range(col, n), key=lambda r: abs(M[r][col]))
        if abs(M[pivot][col]) < 1e-18:
            raise ValueError('singular matrix')
        if pivot != col:
            M[col], M[pivot] = M[pivot], M[col]
        pv = M[col][col]
        for j in range(col, n + 1):
            M[col][j] /= pv
        for r in range(n):
            if r == col:
                continue
            factor = M[r][col]
            if factor == 0.0:
                continue
            for j in range(col, n + 1):
                M[r][j] -= factor * M[col][j]
    return [M[i][n] for i in range(n)]

def lm_fit(xs, ys, p0, max_iter=300, lam=1e-3):
    p = p0[:]
    r = residuals(xs, ys, p)
    c = sum(v * v for v in r)
    for iteration in range(max_iter):
        J = jacobian(xs, ys, p)
        npar = 4
        JtJ = [[0.0] * npar for _ in range(npar)]
        Jtr = [0.0] * npar
        for row, ri in zip(J, r):
            for i in range(npar):
                Jtr[i] += row[i] * ri
                for j in range(i, npar):
                    JtJ[i][j] += row[i] * row[j]
        for i in range(npar):
            for j in range(i):
                JtJ[i][j] = JtJ[j][i]
        A = [row[:] for row in JtJ]
        for i in range(npar):
            A[i][i] += lam * max(abs(JtJ[i][i]), 1e-12)
        try:
            delta = solve_linear(A, [-v for v in Jtr])
        except ValueError:
            lam *= 10.0
            if lam > 1e14:
                break
            continue
        newp = [p[i] + delta[i] for i in range(npar)]
        # Keep the fitted peak center inside the selected window.
        lo_x = min(xs)
        hi_x = max(xs)
        newp[2] = min(max(newp[2], lo_x), hi_x)
        # Guard against overflow in exp().
        newp[0] = min(max(newp[0], -20.0), 20.0)
        newp[1] = min(max(newp[1], -10.0), 10.0)
        try:
            newr = residuals(xs, ys, newp)
            newc = sum(v * v for v in newr)
        except (OverflowError, ZeroDivisionError):
            newc = float('inf')
        if newc < c:
            improvement = c - newc
            p = newp
            r = newr
            c = newc
            lam = max(lam * 0.3, 1e-15)
            if improvement <= 1e-12 * max(c, 1.0):
                step2 = sum(v * v for v in delta)
                if step2 < 1e-12:
                    break
        else:
            lam *= 3.0
            if lam > 1e14:
                break
    return p, c, iteration + 1

def fit_peak(xs, ys, lo, hi, init_x0, init_gamma):
    wx = []
    wy = []
    for x, y in zip(xs, ys):
        if lo <= x <= hi:
            wx.append(x)
            wy.append(y)
    if not wx:
        raise ValueError('empty fitting window')
    offset0 = min(wy)
    amp0 = max(wy) - offset0
    if amp0 <= 0:
        amp0 = max(wy)
    p0 = [math.log(amp0), math.log(init_gamma), init_x0, offset0]
    p, c, iters = lm_fit(wx, wy, p0)
    return {
        'x0': p[2],
        'gamma': math.exp(p[1]),
        'amplitude': math.exp(p[0]),
        'offset': p[3],
        '_cost': c,
        '_iterations': iters,
        '_npoints': len(wx),
    }

def main():
    xs, ys = load_spectrum()
    d = fit_peak(xs, ys, 1250.0, 1470.0, 1356.6, 20.0)
    g = fit_peak(xs, ys, 1500.0, 1650.0, 1580.1, 15.0)
    td = fit_peak(xs, ys, 2550.0, 2820.0, 2689.4, 25.0)
    result = {
        'D': {k: d[k] for k in ('x0', 'gamma', 'amplitude', 'offset')},
        'G': {k: g[k] for k in ('x0', 'gamma', 'amplitude', 'offset')},
        '2D': {k: td[k] for k in ('x0', 'gamma', 'amplitude', 'offset')},
        'ID_IG': d['amplitude'] / g['amplitude'],
    }
    with open('/app/results.json', 'w') as f:
        json.dump(result, f, indent=2)
    print(json.dumps(result, indent=2))
    print('diagnostics:', {'D': {k: v for k, v in d.items() if k.startswith('_')},
                            'G': {k: v for k, v in g.items() if k.startswith('_')},
                            '2D': {k: v for k, v in td.items() if k.startswith('_')}})

if __name__ == '__main__':
    main()
